  //                       none grey (no call, not measured, nothing recorded); meth crimson = methylated, any class
  //   interaction partner rna purple, dna gold, protein teal, self pale teal (another copy of the same protein)
  //   evidence level      ev ink: solid = experimental, hollow and dashed = predicted only
  //   sequence features   domain, disorder (dis: the chain's wave), RG/RGG (rg), composition (bias), region, dense window
  //   3D                  domain3d, rg3d, chain3d: the same hues a step stronger for lit cartoons (features3d)
  //   other marks         kme magenta (lysine methylation), ptm grey, variant grey, mark ink (a feature at a methyl-R)
  //   quantities          seq neutral ramp for counts (4-step scales use its last four); up red / down slate for more
  //                       / less than expected (log2 odds ratios, enrichment bars, matrices)
  //   selection           the page's accent orange (pal.accent, --accent): the current search or filter, as in the
  //                       Filtered flag, wherever a dataset figure marks it
  // Conventions with their own colours stay as published: pLDDT bands, EMBOSS charge (blue +, red -), element and
  // residue-chemistry colours.
  const TOKENS = {
    light: {
      st1: '#2A78D6', st2: '#EB6834', st2s: '#A23B12', stMix: '#1BAF7A', none: '#A3AEB3', meth: '#B4485F',
      rna: '#7B4FBF', dna: '#B7791F', protein: '#0E7490', self: '#7FA9B6', other: '#8A99A3', ev: '#0F3B47',
      rnaBg: 'rgba(123,79,191,0.14)', dnaBg: 'rgba(183,121,31,0.16)', proteinBg: 'rgba(14,116,144,0.12)', rnaInk: '#5B3A96', dnaInk: '#7A4F10', proteinInk: '#0B5A70',
      domain: '#B9DDE6', domainInk: '#0F3B47', dis: '#8796A0', rg: '#F5D6DE', rgInk: '#7A2E45',
      bias: '#FDE3D4', region: '#E3ECF6', dense: 'rgba(17,24,39,0.07)',
      kme: '#A21CAF', ptm: '#6B7F88', variant: '#8A99A3', mark: '#111827', arg: '#155E75',
      domain3d: '#6FB8CF', rg3d: '#E08AA3', chain3d: '#DCE3E7',
      seq: ['#DCE2E5', '#B3BFC5', '#8396A0', '#566A73', '#26343B'], rnaPale: '#CDB8EE', dnaPale: '#EBD3A6',
      up: ['#F6D0CD', '#EF9A94', '#E34948', '#A8302F'], down: ['#DCE3E7', '#A9B7BF', '#6C818C', '#3B4F5A'], mid: '#F0EFEC',
    },
    dark: {
      st1: '#3987E5', st2: '#D95926', st2s: '#F4A26B', stMix: '#199E70', none: '#6D7D84', meth: '#E0708A',
      rna: '#A98BE0', dna: '#D9A548', protein: '#3FB5CF', self: '#6E98A5', other: '#7E8E95', ev: '#D7EEF3',
      rnaBg: 'rgba(123,79,191,0.3)', dnaBg: 'rgba(183,121,31,0.3)', proteinBg: 'rgba(63,181,207,0.22)', rnaInk: '#D2BDF5', dnaInk: '#EFCA85', proteinInk: '#9BDDEC',
      domain: '#1F5566', domainInk: '#E3F4F8', dis: '#8FA6B0', rg: '#5A2C3A', rgInk: '#F6C9D6',
      bias: '#4A2A1C', region: '#213847', dense: 'rgba(232,239,242,0.09)',
      kme: '#D46BE0', ptm: '#8FA3AB', variant: '#7E8E95', mark: '#F3F6F7', arg: '#6CC6DB',
      domain3d: '#4E9DB3', rg3d: '#C06C86', chain3d: '#D0D9DD',
      seq: ['#2E3B41', '#3F5059', '#5C717B', '#8DA2AB', '#C9D6DB'], rnaPale: '#5B4A80', dnaPale: '#6B5530',
      up: ['#5A2523', '#8E3330', '#D2524F', '#F09A95'], down: ['#26343B', '#3D5260', '#6C8592', '#A9BDC7'], mid: '#1A2D35',
    },
  };
  const cssVar = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  const themeName = () => {
    const t = document.documentElement.getAttribute('data-theme');
    return t === 'dark' || (t !== 'light' && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light';
  };
  // --t-<token> (lists: --t-<token>-<k>) on the root element, for explorer.css.
  function applyTokens(name) {
    const st = document.documentElement.style;
    for (const [k, v] of Object.entries(TOKENS[name || themeName()])) {
      if (Array.isArray(v)) v.forEach((c, i) => st.setProperty('--t-' + k + '-' + i, c));
      else st.setProperty('--t-' + k, v);
    }
  }
  // Figure chrome: background, text and rules. Exports and print are always light.
  const EXPORT_PAL = Object.assign({
    bg: '#FFFFFF', ink: '#111827', muted: '#5F6F78', grid: '#E0E8EB', backbone: '#9AA6B2', stem: '#C7D4D9',
    backboneFill: '#EEF5F7', backboneEdge: '#C7D4D9', rtick: '#C7D4D9', ring: '#FFFFFF', panel: '#EEF5F7',
    brush: 'rgba(194,65,12,0.16)', accent: '#C2410C', font: 'Arial, Helvetica, "Liberation Sans", sans-serif',
  }, TOKENS.light);
  function screenPalette() {
    const v = cssVar;
    return Object.assign({
      bg: v('--surface'), ink: v('--ink'), muted: v('--muted'), grid: v('--line'), backbone: v('--line-strong'), stem: v('--line-strong'),
      backboneFill: v('--surface-2'), backboneEdge: v('--line-strong'), rtick: v('--line-strong'), ring: v('--surface'), panel: v('--surface-2'),
      brush: v('--fig-brush'), accent: v('--accent'), font: v('--font-body'),
    }, TOKENS[themeName()]);
  }
  // Shared marks, so a feature looks the same in every figure; sizes come from the figure. attr carries class, data-*
  // and tooltip attributes.
  const MARK = {
    // A disordered stretch of the chain: a shallow wave, lower than the chain bar, in the disorder grey (half-waves
    // about 7 units long, so a long disordered region reads as calm rather than as a scribble).
    wave: (pal, x, y, w, amp) => {
      const n = Math.max(2, Math.round(w / 7)), h = w / n;
      let d = 'M' + r1(x) + ' ' + r1(y);
      for (let k = 0; k < n; k++) d += 'Q' + r1(x + (k + 0.5) * h) + ' ' + r1(y + (k % 2 ? 1.3 : -1.3) * amp) + ' ' + r1(x + (k + 1) * h) + ' ' + r1(y);
      return '<path d="' + d + '" fill="none" stroke="' + pal.dis + '" stroke-width="1.4" stroke-linejoin="round"/>';
    },
    domain: (pal, x, y, w, h, repeat, attr) => '<rect x="' + r1(x) + '" y="' + r1(y) + '" width="' + r1(Math.max(2, w)) + '" height="' + r1(h) + '" rx="3" fill="' + pal.domain + '"' + (repeat ? ' fill-opacity="0.7"' : '') + (attr || '') + '/>',
    // A residue range from a model rather than an experiment: pale, with a dashed edge (left off below 4 units, where
    // dashes would only scribble).
    predBox: (x, y, w, h, color, op, attr) => MARK.box(x, y, w, h, color, ' fill-opacity="' + op + '"' + (w >= 4 ? ' stroke="' + color + '" stroke-width="0.7" stroke-dasharray="2 1.2"' : '') + (attr || '')),
    box: (x, y, w, h, fill, attr) => '<rect x="' + r1(x) + '" y="' + r1(y) + '" width="' + r1(Math.max(1.5, w)) + '" height="' + r1(h) + '" rx="1" fill="' + fill + '"' + (attr || '') + '/>',
    tick: (x, y, h, fill, attr, w) => '<rect x="' + r1(x - (w || 2) / 2) + '" y="' + r1(y - h / 2) + '" width="' + (w || 2) + '" height="' + r1(h) + '" rx="0.6" fill="' + fill + '"' + (attr || '') + '/>',
    diamond: (x, y, size, fill, stroke, attr) => '<rect x="' + r1(x - size / 2) + '" y="' + r1(y - size / 2) + '" width="' + size + '" height="' + size + '" transform="rotate(45 ' + r1(x) + ' ' + r1(y) + ')" fill="' + fill + '" stroke="' + stroke + '" stroke-width="1.1"' + (attr || '') + '/>',
    // A lower-confidence site head: a rim in its colour, hatched with diagonal chords, so it reads apart from a site in
    // print and in grey as well.
    // A site's head draws a light outline around its disc, so its colour reads at about r - 1; the hatched head stays
    // inside that (0.68 r) and is drawn semi-transparent, so it reads as the weaker mark next to a site.
    hatch: (pal, x, y, r0, color, attr, stroke) => {
      const r = Math.max(1.8, r0 * 0.68);
      let d = '';
      for (const off of [-r * 0.5, 0, r * 0.5]) {
        const h = (Math.sqrt(r * r - off * off) - 0.4) / Math.SQRT2, cx0 = x + off / Math.SQRT2, cy0 = y + off / Math.SQRT2;
        d += 'M' + r1(cx0 - h) + ' ' + r1(cy0 + h) + 'L' + r1(cx0 + h) + ' ' + r1(cy0 - h);
      }
      return '<g' + (attr || '') + '><circle cx="' + r1(x) + '" cy="' + r1(y) + '" r="' + r1(r) + '" fill="' + pal.bg + '" fill-opacity="0.6" stroke="' + (stroke || color) + '" stroke-opacity="0.8" stroke-width="0.9"/>' +
        '<path d="' + d + '" fill="none" stroke="' + color + '" stroke-opacity="0.7" stroke-width="0.75" stroke-linecap="round"/></g>';
    },
    // A site head: solid in its colour, or hollow with a dashed rim (predicted only; measured but unchanged).
    head: (pal, x, y, r, color, hollow, attr, stroke) => '<circle cx="' + r1(x) + '" cy="' + r1(y) + '" r="' + r + '" fill="' + (hollow ? pal.bg : color) + '" stroke="' + (hollow ? color : stroke || pal.ring) + '" stroke-width="' + (hollow ? 1.6 : 1.4) + '"' + (hollow ? ' stroke-dasharray="2.2 1.4"' : '') + (attr || '') + '/>',
    ring: (x, y, r, color, dashed, attr) => '<circle cx="' + r1(x) + '" cy="' + r1(y) + '" r="' + r + '" fill="none" stroke="' + color + '" stroke-width="1.6"' + (dashed ? ' stroke-dasharray="1.5 1.2"' : '') + (attr || '') + '/>',
  };
  // A mark with a native SVG tooltip (exports keep it; the page's own tooltips use data-tip).
  const titled = (svg, text) => (svg.endsWith('</g>') ? svg.slice(0, -4) + '<title>' + esc(text) + '</title></g>'
    : svg.replace(/\/>$/, '><title>' + esc(text) + '</title></' + svg.match(/^<(\w+)/)[1] + '>'));
  // A site's head: hatched for a lower-confidence site, else solid or hollow (MARK.head).
  const siteHead = (s, pal, x, y, r, color, hollow, attr, stroke) => (s.lc ? MARK.hatch(pal, x, y, r, color, attr, stroke) : MARK.head(pal, x, y, r, color, hollow, attr, stroke));
  // Width of a label in a figure's font (pal.font; exports use EXPORT_PAL's), so labels are spaced and wrapped by
  // what they occupy rather than by character count.
  const measureCtx = document.createElement('canvas').getContext('2d');
  function textW(text, fs, pal, weight) {
    measureCtx.font = (weight || 400) + ' ' + fs + 'px ' + ((pal && pal.font) || EXPORT_PAL.font);
    return measureCtx.measureText(String(text)).width;
  }
  const fitFs = (text, fs, maxW, pal, weight) => r1(Math.min(fs, fs * maxW / Math.max(1, textW(text, fs, pal, weight))));
  // A legend that wraps onto as many lines as the width needs, so nothing is cut off in exports or print.
  // items: [[draw(x, yMid) -> svg, label], ...] with a 20-px swatch; returns { svg, h }.
  function svgLegend(pal, items, x0, y0, width, o = {}) {
    const fs = o.fs || 10.5, lh = fs + 7, sw = o.sw || 20;
    let x = x0, y = y0 + fs * 0.5, svg = '';
    if (o.title) {
      svg += '<text x="' + r1(x) + '" y="' + r1(y + fs * 0.36) + '" font-size="' + fs + '" font-weight="700" fill="' + pal.muted + '">' + esc(o.title) + '</text>';
      x += textW(o.title, fs, pal, 700) + 10;
    }
    for (const [draw, label] of items) {
      const w = sw + 5 + textW(label, fs, pal);
      if (x > x0 && x + w > x0 + width) { x = x0 + (o.indent || 0); y += lh; }
      svg += draw(x, y) + '<text x="' + r1(x + sw + 5) + '" y="' + r1(y + fs * 0.36) + '" font-size="' + fs + '" fill="' + pal.ink + '">' + esc(label) + '</text>';
      x += w + 14;
    }
    return { svg, h: y - y0 + fs * 0.5 + 2 };
  }
  // Legend swatches for the shared marks.
  const SWATCH = {
    head: (pal, color, hollow) => (x, y) => MARK.head(pal, x + 10, y, 4.6, color, hollow),
    hatch: (pal, color) => (x, y) => MARK.hatch(pal, x + 10, y, 4.6, color),
    disorder: (pal) => (x, y) => '<rect x="' + r1(x) + '" y="' + r1(y - 3) + '" width="5" height="6" rx="2" fill="' + pal.backboneFill + '" stroke="' + pal.backboneEdge + '"/>' +
      MARK.wave(pal, x + 5, y, 15, 2.5),
    domain: (pal) => (x, y) => MARK.domain(pal, x, y - 6, 20, 12),
    fill: (color, op) => (x, y) => '<rect x="' + r1(x) + '" y="' + r1(y - 5) + '" width="20" height="10" rx="2" fill="' + color + '"' + (op ? ' fill-opacity="' + op + '"' : '') + '/>',
    tick: (color) => (x, y) => MARK.tick(x + 10, y, 12, color, '', 2.4),
    diamond: (fill, stroke) => (x, y) => MARK.diamond(x + 10, y, 6, fill, stroke),
    pred: (pal) => (x, y) => MARK.predBox(x, y - 5, 20, 10, pal.protein, 0.3),
  };
  // Legend entries for marks drawn in several figures, so each reads the same everywhere.
  const KEY = {
    domain: (pal) => [SWATCH.domain(pal), 'Domain, repeat or zinc finger (UniProt)'],
    disorder: (pal, mobi) => [SWATCH.disorder(pal), 'Disordered (' + (mobi ? 'MobiDB' : 'UniProt') + ')'],
    rg: (pal) => [SWATCH.fill(pal.rg), 'RG/RGG-rich segment'],
    kme: (pal) => [SWATCH.tick(pal.kme), 'Lys methylation'],
    // The interaction-evidence lanes (contactLanes), in their order.
    lanes: (pal) => [[SWATCH.tick(pal.rna), 'RNA'], [SWATCH.tick(pal.dna), 'DNA'], [SWATCH.fill(pal.protein, 0.85), 'Another protein'], [SWATCH.fill(pal.self, 0.85), 'Same protein (self-contact)'], [SWATCH.pred(pal), 'Predicted protein contact']]
      .concat(showIntact() ? [[SWATCH.diamond(pal.protein, pal.ring), 'Mutation changes an interaction (IntAct)']] : [])
      .concat([[(x, y) => MARK.ring(x + 10, y, 4.2, pal.ink, false), 'Evidence at that methylarginine'],
        [(x, y) => MARK.ring(x + 10, y, 4.2, pal.ink, true), 'Weaker: nearby, in a fragment, or predicted only']]),
  };

  // ------------------------------------------------------------------ model
  let M = null;      // meta
  let P = [];        // proteins
  let S = [];        // sites
  let IDX = null;    // lookup maps
  let R = null;      // current filtered result
  let evidencePromise = null;
  const uniprotCache = new Map();
  const UNIDATA = new Map();   // accession -> resolved UniProt features (or null)
  const REFMD5 = new Map();    // accession -> MD5 of the reference sequence the site positions refer to
  const afCache = new Map();
  const AFDATA = new Map();    // accession -> resolved AlphaFold data (or null)
  let mol = null;              // live 3Dmol viewer for the open protein

  const DEFAULT_FILTERS = () => ({
    // Motif, study, domain class, functional class, disease, condensate, complex, GO and partner filters are search
    // terms (motif:RGG …) held in Q, not here.
    states: new Set(), ips: new Set(), sources: new Set(), s2: new Set(), multi: false, reviewed: false, minRep: 0,
    treat: '', disorder: new Set(), domctx: new Set(),
    nn: 0, ptmGroup: '', ptmDist: 0,
    anyCond: false, minSites: 1, dense: false, arch: '', argEnriched: false,
    ixScore: 700, goExp: false, iface: new Set(), condConf: 0, modelledPdb: false, pred: 0, galOnly: false, xl: new Set(),
    evAll: 0, evExact: false, pevAll: 0, pevExact: false,
    // Selection-profile features the sites must all have (comma-separated keys of profileFeatures()), so a click on a
    // feature or a connections-matrix row keeps exactly the sites its count was taken from.
    feats: '',
    // The gallery settings a "best-supported predicted contact" filter was made with (galEncode), '' for the default.
    galSet: '',
  });
  const cloneFilters = (f) => {
    const out = {};
    for (const k of Object.keys(f)) out[k] = f[k] instanceof Set ? new Set(f[k]) : f[k];
    return out;
  };
  let F = DEFAULT_FILTERS();
  let Q = { raw: '', plain: '', proteins: null, positions: null, note: '', tokens: [], errors: [], siteT: [], protT: [] };
  const UI = {
    view: 'overview', detail: null, highlight: null,
    sortP: { key: 'sites', dir: -1 }, sortS: { key: 'gene', dir: 1 },
    pageP: 50, pageS: 100, zoom: null, openEvidence: new Set(),
    allCond: false, funcExpanded: false, charts: {},
    fig: { color: 'state', labels: 'auto', tracks: new Set(mapTracks0()), order: Array.isArray(mapPrefs.order) ? mapPrefs.order : null },
    ixTab: 'proteins', ixTop: 20, ixMin: 700, ixColor: 'sites', ixAll: false, ixNet: null, net: netPrefs, ixRing: true,
    cxPred: false, cxMin: 3, cxSort: 'q', cxAll: false, refsOpen: new Set(), ctx: 'protein', condThr: 3, pendingContact: null, pendingModel: null, ixOpen: new Set(), ixJump: null,
    gal: { conf: 'confident', pl: 80, kind: 'bond', noPdb: false, xl: false, all: false },
    figs: { flank: 7, rows: 50, order: 'protein', logo: 'freq', nProt: 8, scale: 'common', color: 'state', lanes: true, sortP: 'default', prot: null }, consPos: null, consFlank: 10, docJump: null,
    evTop: 1, evAllRows: false, evMode: 'sites', cxOpen: new Set(), ixScrollMap: false, reportPrint: false,
  };

  // ------------------------------------------------------------------- load
  fetch(dataUrl('methylarg_sites.json'))
    .then((r) => { if (!r.ok) throw new Error(r.status + ' ' + r.statusText); return r.json(); })
    .then(init)
    .catch((err) => {
      if (LC_ON) {
        $('#loading').innerHTML = '<div class="empty"><b>The data with lower-confidence sites did not load</b>' +
          'Could not read <code>data/methylarg_sites_all.json</code> (' + esc(err.message) + '). <a href="' + esc(lcUrl(false)) + '">Open the page without them</a>.</div>';
        return;
      }
      $('#loading').innerHTML = '<div class="empty"><b>The site data did not load</b>' +
        'Could not read <code>data/methylarg_sites.json</code> (' + esc(err.message) + '). ' +
        'If you opened index.html from disk, serve the folder instead, for example <code>python -m http.server</code> inside <code>docs/</code>.</div>';
    });

  function loadEvidence() {
    if (!evidencePromise) {
      evidencePromise = fetch(dataUrl('methylarg_evidence.json'))
        .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
        .catch(() => { evidencePromise = null; return null; });   // not cached: the next call tries again
    }
    return evidencePromise;
  }

  function loadUniProt(acc) {
    if (uniprotCache.has(acc)) return uniprotCache.get(acc);
    const fields = 'accession,length,sequence,sequence_version,protein_name,gene_primary,cc_function,ft_domain,ft_repeat,ft_zn_fing,ft_region,ft_compbias,ft_motif,ft_variant,ft_mutagen,ft_mod_res,cc_disease,xref_ensembl';
    const ctrl = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = ctrl ? setTimeout(() => ctrl.abort(), 20000) : null;
    const promise = fetch('https://rest.uniprot.org/uniprotkb/' + encodeURIComponent(acc) + '.json?fields=' + fields,
      ctrl ? { signal: ctrl.signal } : undefined)
      .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then((d) => {
        const desc = d.proteinDescription || {};
        const nameObj = desc.recommendedName || (desc.submissionNames || [])[0] || {};
        const seq = (d.sequence && d.sequence.value) || '';
        const all = (d.features || []).map((f) => {
          const alt = f.alternativeSequence || {};
          return {
            type: f.type, desc: f.description || '',
            start: f.location && f.location.start && f.location.start.value,
            end: f.location && f.location.end && f.location.end.value,
            from: alt.originalSequence || '', to: (alt.alternativeSequences || []).join('/'), id: f.featureId || '',
          };
        }).filter((f) => f.start && f.end);
        const special = ['Natural variant', 'Mutagenesis', 'Modified residue'];
        const out = {
          seq,
          len: (d.sequence && d.sequence.length) || null,
          name: (nameObj.fullName && nameObj.fullName.value) || '',
          gene: (d.genes && d.genes[0] && d.genes[0].geneName && d.genes[0].geneName.value) || '',
          feats: all.filter((f) => !special.includes(f.type)),
          variants: all.filter((f) => f.type === 'Natural variant'),
          mutagen: all.filter((f) => f.type === 'Mutagenesis'),
          methylR: new Map(all.filter((f) => f.type === 'Modified residue' && /arginine/i.test(f.desc) && /methyl/i.test(f.desc)).map((f) => [f.start, f.desc])),
          rg: rgBoxes(seq),
          diseases: (d.comments || []).filter((c) => c.commentType === 'DISEASE').map((c) => ({
            name: (c.disease && c.disease.diseaseId) || '', acronym: (c.disease && c.disease.acronym) || '', id: (c.disease && c.disease.diseaseAccession) || '',
            mim: ((c.disease && c.disease.diseaseCrossReference) || {}).id || '', desc: (c.disease && c.disease.description) || '',
            note: ((c.note && c.note.texts) || []).map((t) => t.value).join(' '),
          })).filter((x) => x.name),
          ensg: Array.from(new Set((d.uniProtKBCrossReferences || []).filter((x) => x.database === 'Ensembl')
            .map((x) => ((x.properties || []).find((pp) => pp.key === 'GeneId') || {}).value || '').filter(Boolean).map((g) => g.split('.')[0]))),
          md5: (d.sequence && d.sequence.md5) || '',
          seqVersion: (d.entryAudit && d.entryAudit.sequenceVersion) || null,
          func: (d.comments || []).filter((c) => c.commentType === 'FUNCTION').flatMap((c) => (c.texts || []).map((t) => t.value)).join(' '),
          drift: false,
        };
        // Site positions refer to the dataset's reference sequence. When the current UniProt sequence differs, its
        // positional annotations (sequence, features, variants, modified residues) need not line up with the sites,
        // so they are left out; name, gene, diseases and cross-references are kept.
        const ref = REFMD5.get(acc);
        if (ref && out.md5 && ref !== out.md5) {
          Object.assign(out, { drift: true, seq: '', len: null, feats: [], variants: [], mutagen: [], methylR: new Map(), rg: [] });
        }
        return out;
      })
      .catch(() => null)
      .then((d) => { UNIDATA.set(acc, d); if (!d) uniprotCache.delete(acc); return d; })   // a failure shows, and the next visit tries again
      .finally(() => { if (timer) clearTimeout(timer); });
    uniprotCache.set(acc, promise);
    return promise;
  }

  // UniProt's own modified-residue term for a methylarginine, shortened.
  function uniprotMethylLabel(desc) {
    const d = desc.toLowerCase();
    const t = d.includes('asymmetric') ? 'Rme2a' : d.includes('symmetric') ? 'Rme2s' : d.includes('dimethyl') ? 'Rme2' : d.includes('methyl') ? 'Rme1' : 'modified';
    return t + (d.includes('alternate') ? ' (alt.)' : '');
  }

  // ------------------------------------------------------------- AlphaFold
  const fetchJson = (u) => fetch(u).then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); });
  const fetchText = (u) => fetch(u).then((r) => { if (!r.ok) throw new Error(r.status); return r.text(); });

  // AlphaFold DB entry for an accession: per-residue pLDDT and, for arginines, AlphaMissense R->X scores.
  function loadAF(acc) {
    if (afCache.has(acc)) return afCache.get(acc);
    const pr = fetchJson('https://alphafold.ebi.ac.uk/api/prediction/' + encodeURIComponent(acc))
      .then((list) => {
        const entries = Array.isArray(list) ? list : [];
        // Only the model of this very accession: for proteins over 2,700 residues AFDB returns isoform models alone,
        // whose numbering does not match the canonical sites.
        const e = entries.find((x) => x.uniprotAccession === acc);
        if (!e) return null;
        return Promise.all([
          e.plddtDocUrl ? fetchJson(e.plddtDocUrl).catch(() => null) : null,
          e.amAnnotationsUrl ? fetchText(e.amAnnotationsUrl).catch(() => null) : null,
        ]).then(([conf, am]) => {
          const plddt = new Map();
          if (conf && conf.residueNumber) conf.residueNumber.forEach((r, k) => plddt.set(r, conf.confidenceScore[k]));
          const amR = new Map();
          if (am) {
            for (const line of am.split('\n')) {
              if (line.charCodeAt(0) !== 82) continue; // rows starting with 'R' (arginine substitutions)
              const [v, sc, cls] = line.split(',');
              const m = /^R(\d+)[A-Z]$/.exec(v);
              if (!m) continue;
              const pos = +m[1];
              let a = amR.get(pos);
              if (!a) amR.set(pos, (a = { sum: 0, n: 0, lp: 0, max: 0 }));
              const s = +sc;
              a.sum += s; a.n++; a.max = Math.max(a.max, s);
              if (/path/i.test(cls || '')) a.lp++;
            }
          }
          return { entry: e, plddt, am: amR, seq: e.uniprotSequence || e.sequence || '' };
        });
      })
      .catch(() => null)
      .then((d) => { AFDATA.set(acc, d); return d; });
    afCache.set(acc, pr);
    return pr;
  }

  // 3Dmol.js lights a scene with one directional light and no ambient term, so faces turned away from it go black
  // and ambient occlusion darkens the rest. Its lighting shaders are patched as WebGL compiles them (3Dmol does not
  // export its shader library), so every face also gets a fixed share of fill light: FILL + (1 - FILL) * max(n·l, 0).
  // Only shader sources that use 3Dmol's light uniforms or varyings are touched.
  const FILL_LIGHT = 0.3;
  function addFillLight(lib) {
    if (addFillLight.done) return lib;
    addFillLight.done = true;
    const f = FILL_LIGHT.toFixed(2), g = (1 - FILL_LIGHT).toFixed(2);
    for (const C of [window.WebGLRenderingContext, window.WebGL2RenderingContext]) {
      if (!C || !C.prototype || !C.prototype.shaderSource) continue;
      const orig = C.prototype.shaderSource;
      C.prototype.shaderSource = function (shader, src) {
        if (typeof src === 'string' && /directionalLight|vLight/.test(src)) src = src.replace(/max\( (-?)dotProduct, 0\.0 \)/g, (m, neg) => '(' + f + ' + ' + g + ' * max( ' + neg + 'dotProduct, 0.0 ))');
        return orig.call(this, shader, src);
      };
    }
    lib.__fillLight = FILL_LIGHT;
    return lib;
  }
  function load3Dmol() {
    if (window.$3Dmol) return Promise.resolve(window.$3Dmol);
    if (!load3Dmol.p) {
      load3Dmol.p = new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = 'https://cdnjs.cloudflare.com/ajax/libs/3Dmol/2.5.3/3Dmol-min.js';
        s.async = true;
        s.onload = () => (window.$3Dmol ? resolve(addFillLight(window.$3Dmol)) : reject(new Error('3Dmol missing')));
        s.onerror = () => { load3Dmol.p = null; reject(new Error('3Dmol failed to load')); };
        document.head.appendChild(s);
      });
    }
    return load3Dmol.p;
  }

  // RG/RGG-rich segments: runs of >=3 RG dipeptides whose consecutive RG arginines are at most 12 residues apart.
  function rgBoxes(seq) {
    const out = [];
    let cur = null;
    const close = () => { if (cur && cur.n >= 3) out.push(cur); };
    for (let k = 0; k < seq.length - 1; k++) {
      if (seq[k] !== 'R' || seq[k + 1] !== 'G') continue;
      const pos = k + 1;
      const rgg = seq[k + 2] === 'G' ? 1 : 0;
      if (cur && pos - cur.last <= 12) { cur.last = pos; cur.n++; cur.rgg += rgg; cur.end = pos + 1 + rgg; }
      else { close(); cur = { start: pos, last: pos, end: pos + 1 + rgg, n: 1, rgg }; }
    }
    close();
    return out.map((c) => ({ start: c.start, end: c.end, n: c.n, rgg: c.rgg, label: c.rgg >= 2 ? 'RGG-rich' : 'RG-rich' }));
  }

  function init(data) {
    M = data.meta;
    M.vi = { disordered: M.disorder_classes.indexOf('disordered') };
    M.studyOrder = M.studies.map((st, k) => k).sort((a, b) => M.studies[b][2] - M.studies[a][2]);
    M.subParent = {};
    for (const r of M.overview.functional_subclasses || []) M.subParent[r[0]] = r[6];
    // Fields added after the first twenty (protein) or twenty (site) are found by name; older exports lack them.
    const named = (fields, row, name, empty) => { const k = fields.indexOf(name); return k >= 0 && row[k] != null ? row[k] : empty; };
    P = data.proteins.map((r, i) => ({
      i, acc: r[0], gene: r[1] || '', name: r[2] || '', uid: r[3] || '', func: r[4], sub: r[5], len: r[6],
      argN: r[7], shrink: r[8], argQ: r[9], iso: r[0].includes('-'), cond: r[11], dis: r[12], als: !!r[13],
      dens: r[14], best: r[15], sig: r[16], arch: r[17], ptms: r[18], aliases: r[19] || [], sites: [],
      ref: named(M.protein_fields, r, 'reference_md5', ''), hpa: named(M.protein_fields, r, 'hpa_locations', []),
      idr: named(M.protein_fields, r, 'disorder_intervals', null),
      // [family index, family terms naming the gene] for every audited family whose gene set holds it (null: not exported).
      disFam: named(M.protein_fields, r, 'disease_families', null),
      pan: named(M.protein_fields, r, 'panther', null),
      doTerms: null,
    }));
    for (const p of P) if (p.ref) REFMD5.set(p.acc, p.ref);
    // Disease Ontology: each protein's most specific tested terms, with every term above them.
    const k_do = M.protein_fields.indexOf('disease_ontology_terms');
    if (k_do >= 0 && doMeta()) {
      const T = doMeta().terms;
      data.proteins.forEach((r, i) => {
        const seen = new Set(), todo = (r[k_do] || []).slice();
        while (todo.length) { const k = todo.pop(); if (!seen.has(k)) { seen.add(k); todo.push(...T[k][2]); } }
        P[i].doTerms = seen;
      });
    }
    S = data.sites.map((r, j) => ({
      j, p: r[0], pos: r[1], st: r[2], src: r[3], refs: r[4], dc: r[5], dEdge: r[6], dctx: r[7], ipr: r[8],
      dcls: r[9], domDist: r[10], domSide: r[11], win: r[12], mot: r[13], mis: !!r[14], orig: r[15],
      s2: r[16], ip: r[17], tr: r[18], study: r[19] || 0, ko: named(M.site_fields, r, 'carm1_ko', []), stx: named(M.site_fields, r, 'state_detail', null), par: named(M.site_fields, r, 'paralogs', null), nn: null, ptmD: null, trf: 0,
      iface: 0, ifP: null, ifPdb: null, ifN: 0, contacts: null, modelledMe: '', geo: null, modelled: null,
    }));
    for (const s of S) P[s.p].sites.push(s.j);
    // The view with lower-confidence sites marks them, with what the tests found (M.lower_confidence_sites).
    const LCS = M.lower_confidence_sites;
    if (LCS) for (const [j, an, res, why, earlier] of LCS.sites) Object.assign(S[j], { lc: true, lcAn: !!an, lcRes: res, lcWhy: why, lcEarlier: earlier || [] });
    // Unreviewed (TrEMBL) entries have no Swiss-Prot entry name. Their sites often repeat a site of the reviewed entry
    // of the same gene at the same position; keep both (the union as published) but flag the repeat.
    const reviewedByGene = new Map();
    for (const p of P) {
      p.unrev = !p.uid || p.uid === p.acc.split('-')[0] + '_HUMAN';
      if (!p.unrev && p.gene) { if (!reviewedByGene.has(p.gene)) reviewedByGene.set(p.gene, []); reviewedByGene.get(p.gene).push(p); }
    }
    for (const p of P) {
      if (!p.unrev) continue;
      p.reviewedTwin = (reviewedByGene.get(p.gene) || [])[0] || null;
      for (const j of p.sites) {
        for (const q of reviewedByGene.get(p.gene) || []) {
          const k = q.sites.find((x) => S[x].pos === S[j].pos);
          if (k != null) { S[j].dup = k; break; }
        }
      }
    }

    for (const p of P) {
      p.hist = HISTONE_GENE.test(p.gene) || (!p.gene && HISTONE_NAME.test(p.name));
      p.label = p.gene || p.acc;
      p.maxPos = p.sites.length ? S[p.sites[p.sites.length - 1]].pos : 0;
      p.ptmPos = [[], [], [], []];
      for (const [pos, g] of p.ptms) p.ptmPos[g].push(pos);
      p.ptmPos.forEach((a) => a.sort((x, y) => x - y));
      const ss = p.sites;
      for (let k = 0; k < ss.length; k++) {
        const s = S[ss[k]];
        const prev = k > 0 ? s.pos - S[ss[k - 1]].pos : Infinity;
        const next = k < ss.length - 1 ? S[ss[k + 1]].pos - s.pos : Infinity;
        const d = Math.min(prev, next);
        s.nn = Number.isFinite(d) ? d : null;
        s.ptmD = p.ptmPos.map((arr) => nearestDistance(arr, s.pos));
      }
      p.nIdr = ss.reduce((n, j) => n + (S[j].dc === M.vi.disordered ? 1 : 0), 0);
    }
    for (const s of S) {
      for (const e of s.tr) {
        const dir = trDir(e);
        if (dir) s.trf |= 1 << (e[1] * 2 + (dir === 'down' ? 0 : 1));
      }
      for (const c of s.ko) s.trf |= (c[4] ? TRF_KO_DOWN : 0) | (c[5] ? TRF_KO_UP : 0);
    }
    IDX = { gene: new Map(), acc: new Map(), uid: new Map(), alias: new Map() };
    const add = (map, key, i) => { if (!key) return; key = key.toUpperCase(); if (!map.has(key)) map.set(key, []); if (!map.get(key).includes(i)) map.get(key).push(i); };
    for (const p of P) {
      add(IDX.gene, p.gene, p.i);
      add(IDX.acc, p.acc, p.i);
      if (p.acc.includes('-')) add(IDX.acc, p.acc.split('-')[0], p.i);
      add(IDX.uid, p.uid, p.i);
      for (const a of p.aliases) add(IDX.alias, a, p.i);
    }

    const dv = M.provenance && M.provenance.dataset_version;
    $('#data-version').innerHTML = (dv ? 'dataset <a href="https://github.com/Shechterlab/PTM_Pipeline/tree/main/releases/' + encodeURIComponent(dv) + '">' + esc(dv) + '</a> · ' : '') + 'data exported ' + esc(M.generated);
    if (window.matchMedia && window.matchMedia('(max-width: 560px)').matches) $('#q').placeholder = 'Gene, site, gene list or motif:RGG';
    $('#year').textContent = new Date().getFullYear();
    renderHero();
    const params = new URLSearchParams(location.search);
    F = filtersFromParams(params);
    const q0 = [params.get('q') || ''].concat(legacyTerms(params)).join(' ').trim();
    if (params.get('A') != null) UI.cmpA = { qs: params.get('A'), label: params.get('An') || '' };
    if (q0) { $('#q').value = q0; $('#q-clear').hidden = false; Q = parseQuery(q0); }
    renderRail();
    bindGlobal();
    renderLcSwitch();
    bindDocLinks($('footer.site'));
    bindDocLinks($('#lede'));
    compute();
    route();
    loadInteractions();
  }

  function nearestDistance(sorted, pos) {
    if (!sorted.length) return Infinity;
    let lo = 0, hi = sorted.length - 1;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (sorted[mid] < pos) lo = mid + 1; else hi = mid; }
    let d = Math.abs(sorted[lo] - pos);
    if (lo > 0) d = Math.min(d, Math.abs(sorted[lo - 1] - pos));
    return d;
  }

  // ----------------------------------------------------------------- search
  // Exact lookup: accession, current symbol, UniProt entry name, then synonyms and source-reported symbols.
  function lookup(token) {
    const key = token.toUpperCase();
    const hit = IDX.acc.get(key) || IDX.gene.get(key) || IDX.uid.get(key);
    if (hit) return { hit, alias: false };
    const al = IDX.alias.get(key);
    return al ? { hit: al, alias: true } : null;
  }
  const lookupExact = (token) => { const l = lookup(token); return l ? l.hit : null; };

  function parseQuery(text) {
    const raw = text.trim();
    const { plain, tokens, errors } = splitTerms(raw);
    const q = parsePlain(plain);
    Object.assign(q, { raw, plain, tokens, errors, siteT: tokens.filter((t) => t.vals[0].kind === 'site'), protT: tokens.filter((t) => t.vals[0].kind === 'prot') });
    if (errors.length) q.note = (q.note ? q.note + ' ' : '') + '<span class="warn-text">' + errors.map(esc).join(' ') + '</span>';
    return q;
  }
  function parsePlain(text) {
    const raw = text.trim();
    if (!raw) return { raw: '', proteins: null, positions: null, note: '' };
    const tokens = raw.split(/[\s,;]+/).filter(Boolean);
    const proteins = new Set();
    const positions = new Map();
    const missing = [];
    const missingSites = [];
    const viaAlias = [];
    let last = null;
    let histoneNote = false;
    const addPos = (hit, typed) => {
      // Histone positions are typed in histone numbering (no initiator Met): H3C1 R2 is UniProt R3.
      const uni = (i) => typed + (P[i].hist ? 1 : 0);
      for (const i of hit) {
        if (!positions.has(i)) positions.set(i, new Set());
        positions.get(i).add(uni(i));
        proteins.add(i);
        if (P[i].hist) histoneNote = true;
      }
      // A symbol can name several entries (isoforms, unreviewed twins): warn only when none of them has the site.
      if (!hit.some((i) => P[i].sites.some((j) => S[j].pos === uni(i)))) missingSites.push(P[hit[0]].label + ' R' + typed);
    };
    const noteAlias = (tok, l) => { if (l.alias) viaAlias.push(tok + ' → ' + l.hit.map((i) => P[i].label).join('/')); };
    for (const tok of tokens) {
      const l = lookup(tok);
      if (l) { l.hit.forEach((i) => proteins.add(i)); last = l.hit; noteAlias(tok, l); continue; }
      // An isoform accession (P35637-2) names the protein, not a site: its suffix is not a residue number.
      const iso = tok.match(/^([OPQ][0-9][A-Z0-9]{3}[0-9]|[A-NR-Z][0-9](?:[A-Z][A-Z0-9]{2}[0-9]){1,2})-\d+$/i);
      const li = iso && lookup(iso[1]);
      if (li) { li.hit.forEach((i) => proteins.add(i)); last = li.hit; noteAlias(tok, li); continue; }
      let m = tok.match(/^(.+?)[:_/-]R?(\d+)$/i);
      if (m) {
        const lm = lookup(m[1]);
        if (lm) { addPos(lm.hit, +m[2]); last = lm.hit; noteAlias(m[1], lm); continue; }
      }
      m = tok.match(/^R?(\d+)$/i);
      if (m && last) { addPos(last, +m[1]); continue; }
      missing.push(tok);
    }
    if (!proteins.size) {
      const t = raw.toLowerCase();
      const hits = P.filter((p) => p.gene.toLowerCase().startsWith(t) || p.acc.toLowerCase().startsWith(t) ||
        p.aliases.some((a) => a.toLowerCase().startsWith(t)) || (t.length >= 3 && p.name.toLowerCase().includes(t)));
      if (hits.length) {
        return { raw, proteins: new Set(hits.map((p) => p.i)), positions: null,
          note: '<b>' + fmt(hits.length) + '</b> protein' + (hits.length === 1 ? '' : 's') + ' match “' + esc(raw) + '” by symbol prefix, synonym or protein name.' };
      }
      const concepts = conceptSuggestions(raw);
      return { raw, proteins: new Set(), positions: null,
        note: 'No protein in the union matches “' + esc(raw) + '”.' + (concepts.length ? ' Did you mean ' + concepts.slice(0, 4).map((c) => '<button class="linkish" type="button" data-setq="' + esc(c.term) + '" title="' + esc(c.sub) + '">' + esc(c.label) + '</button>').join(', ') + '?' : ' Try a gene symbol (PRMT5), a UniProt accession (O14744) or part of a protein name.') };
    }
    const notes = [];
    const matched = tokens.length - missing.length;
    // A gene list gets a count; a single protein with its sites needs none.
    if (tokens.length > 1 && (proteins.size > 1 || missing.length)) notes.push('<b>' + fmt(proteins.size) + '</b> protein' + (proteins.size === 1 ? '' : 's') + ' from ' + fmt(matched) + ' of ' + fmt(tokens.length) + ' search words.');
    if (viaAlias.length) notes.push('Matched by synonym: ' + viaAlias.slice(0, 10).map(esc).join(', ') + '.');
    if (missing.length) notes.push('Not in the methylarginine union: ' + missing.slice(0, 25).map(esc).join(', ') + (missing.length > 25 ? ' and ' + (missing.length - 25) + ' more' : '') + '.');
    if (missingSites.length) notes.push('No methylation reported at ' + missingSites.slice(0, 10).map(esc).join(', ') + '.');
    if (histoneNote) notes.push('Histone residues are numbered without the initiator methionine (H3 R2 is UniProt R3).');
    return { raw, proteins, positions: positions.size ? positions : null, note: notes.join(' ') };
  }

  function suggestions(text) {
    const tok = text.split(/[\s,;]+/).pop() || '';
    if (!tok) return [];
    const t = tok.toLowerCase();
    const exact = [], prefix = [], alias = [], named = [];
    for (const p of P) {
      const g = p.gene.toLowerCase();
      if (g === t || p.acc.toLowerCase() === t) exact.push([p, '']);
      else if (g.startsWith(t) || p.acc.toLowerCase().startsWith(t)) prefix.push([p, '']);
      else {
        const a = p.aliases.find((x) => x.toLowerCase().startsWith(t));
        if (a) alias.push([p, a]);
        else if (t.length >= 3 && p.name.toLowerCase().includes(t)) named.push([p, '']);
      }
    }
    const bySites = (a, b) => b[0].sites.length - a[0].sites.length;
    return exact.concat(prefix.sort(bySites), alias.sort(bySites), named.sort(bySites)).slice(0, 8);
  }

  // ----------------------------------------------------------- search terms
  // Readable filters inside the search, e.g. motif:RGG window:PRPR class:rna-binding disease:als go:rna binds:PRMT5
  // interaction:predicted. A comma inside a term means any of its values (motif:RGG,GAR); separate terms must all
  // match. Every other word still searches genes, accessions and sites, so the search box and the link say exactly
  // what is selected.
  const TERM_KEYS = ['motif', 'window', 'study', 'domain', 'panther', 'class', 'subclass', 'disease', 'dterm', 'doterm', 'condensate', 'location', 'complex', 'go', 'binds', 'interaction', 'confidence'];
  const TERM_GROUP = { motif: 'motif', window: 'motif', study: 'prov', domain: 'struct', panther: 'protein', class: 'protein', subclass: 'protein', disease: 'protein', dterm: 'protein', doterm: 'protein', condensate: 'protein', location: 'protein', complex: 'ix', go: 'ix', binds: 'ix', interaction: 'ix' };
  const TERM_HELP = {
    motif: 'Motif covering the methyl-R: a family (RG, RGG, GRG, GAR, RXR, DR, RD, ER, RE, CARM1-Pro) or a pattern such as GXRG or [RK]XR',
    window: 'Motif anywhere within ±15 aa of the site, e.g. PRPR',
    study: 'Reported by a study or database, e.g. maron-2021, phosphositeplus',
    domain: 'Nearest InterPro domain class (lab domain ontology), e.g. rrm, rna-helicase',
    panther: 'PANTHER protein class: a group of the overview, a top-level class or a subclass, e.g. rna-processing-and-translation, rna-splicing-factor',
    class: 'Functional class (lab protein ontology), e.g. rna-binding, chromatin',
    subclass: 'Functional subclass (lab protein ontology), e.g. hnrnp, chromatin-readers',
    disease: 'Disease family (DisGeNET): the methylated proteins whose gene is in the family\'s gene set (what its test counts), e.g. als, cancer',
    dterm: 'One enriched DisGeNET term, by UMLS id or name: the methylated proteins whose gene it names, e.g. dterm:C2718017 (TDP-43 proteinopathies)',
    doterm: 'One Disease Ontology term, by DOID or name: the methylated proteins whose gene is in the term or a term under it, e.g. doterm:DOID:332 (amyotrophic lateral sclerosis)',
    condensate: 'CD-CODE condensate, e.g. stress-granule, nuclear-speckle',
    location: 'Subcellular location in the Human Protein Atlas (reliability Approved or better), e.g. nucleoli, nuclear-speckles',
    complex: 'Complex Portal complex, by ID (CPX-1234) or name',
    go: 'Gene Ontology binding: rna or dna',
    binds: 'STRING physical partner: prmt, tudor, wd40, phd, methylated, other, or a gene symbol',
    interaction: 'Interaction evidence at the site: experimental, predicted, predicted-only, any or none',
  };
  const TERM_NOUN = { confidence: 'confidence tier', study: 'study or database', domain: 'domain class', panther: 'PANTHER protein class', class: 'functional class', subclass: 'functional subclass', disease: 'disease family', condensate: 'condensate', location: 'HPA location', complex: 'complex' };
  // confidence: (the view with lower-confidence sites): [name, test]
  const CONF_TIERS = [['Site', (s) => !s.lc], ['Paralog-assigned', (s) => !!s.par], ['Lower', (s) => !!s.lc], ['Lower counted', (s) => !!s.lc && s.lcAn], ['Lower shown only', (s) => !!s.lc && !s.lcAn]];
  // the tiers an export has: paralog-assigned sites from v1.2.0, lower-confidence ones in the view with them
  const confTiers = () => CONF_TIERS.map((t, k) => [t, k]).filter(([[n]]) => (n.startsWith('Lower') ? !!M.lower_confidence_sites : n === 'Paralog-assigned' ? S.some((x) => x.par) : true));
  const MOTIF_TERM = { CARM1_proline_rich: 'CARM1-Pro', CARM1_hydrophobic_proline: 'CARM1-Pro-hydrophobic' };
  const motifTerm = (m) => MOTIF_TERM[m] || m;
  const motifFamily = (v) => M.motifs.findIndex((m) => motifTerm(m).toLowerCase() === String(v).toLowerCase());
  const BIND_TERMS = [['prmt', 1], ['tudor', 2], ['wd40', 4], ['phd', 5], ['methylated', 3], ['other', 6]];
  const IX_STATUS_TERMS = [
    ['experimental', 'Experimental interaction evidence', (m) => m & EV_EXP],
    ['predicted', 'Predicted interface or contact', (m) => m & EV_PRED],
    ['predicted-only', 'Predicted only (no experimental evidence)', (m) => (m & EV_PRED) && !(m & EV_EXP)],
    ['any', 'Any interaction evidence', (m) => m & (EV_EXP | EV_PRED)],
    ['none', 'No interaction evidence recorded', (m) => !(m & (EV_EXP | EV_PRED))],   // IntAct records do not set the status
  ];
  const slugify = (s) => String(s).toLowerCase().replace(/['’]/g, '').replace(/[^a-z0-9+]+/g, '-').replace(/^-+|-+$/g, '');
  const termNameCache = {};
  // Names a term can take, each with a short slug (the part before the first " / ", made unique within its list).
