        (!grouped && pool.length > DIS_TERMS_SHOWN ? '<button class="linkish" type="button" id="dis-terms-all">' + (UI.disTermsAll ? 'Show the first ' + DIS_TERMS_SHOWN : 'Show all ' + fmt(pool.length)) + '</button>' : '')
