  const famEff = (r) => r[3];
  const famEffHtml = (r) => (FOLD() ? 'fold enrichment ' : 'OR ') + '<b>' + (r[3] || 0).toFixed(2) + '</b>, q ' + fmtP(r[4]);
  // Disease Ontology (v1.2.0 exports): every term tested, [DOID, name, parent indices, methylated genes, genes, fold
